			}
			remove_variable = ignore_succesion_effect
		}
		else = {
			trigger_event_silently = succession.100 #Partition Inheritance Event
		}
	}

	traverse_family_tree = yes
	sibling_score = {
		if = {
			limit = {
				exists = root
			}
			#bonus for males
			add = {
				desc = "HEIR_SELECTION_MALE_DESC"
				if = {
