# root = country, scope:overlord = country which created the subject, scope:subject_type = subject type of the created country
on_subject_created = {
	effect = {
		if = {
			limit = {
				religion != scope:overlord.religion
				scope:overlord.modifier:force_convert_created_subjects = yes
			}
			change_religion = scope:overlord.religion
		}
		# A military order (e.g. Teutonic Order) creates a subject that inherits
		# the theocracy government type but not the military_order_reform (skipped
		# at creation). Without that reform the subject auto-qualifies for the
		# "bishopric" Catholic Church IO special status, which is unintended.
		# Revert such subjects to monarchy so they get a sensible government.
		if = {
			limit = {
				government_type = government_type:theocracy
				NOT = { has_reform = government_reform:military_order_reform }
				scope:overlord = {
					has_reform = government_reform:military_order_reform
				}
			}
			change_government_type = government_type:monarchy
		}
		if = {
			limit = {
				exists = international_organization:hre
				is_leader_of_international_organization = international_organization:hre
			}
			international_organization_chooses_new_leader = international_organization:hre
		}
	}
}


