#root= location, scope:loser = previous owner, scope:winner = new owner (can be null)
on_location_changed_owner = {
	on_actions = {
		on_timurid_occupy_location_horde
	}
	events = {
		autocephalous_patriarchates.1
		autocephalous_patriarchates.2
		miaphysite_flavor.1
		miaphysite_flavor.3
		miaphysite_flavor.5
		miaphysite_flavor.7
		miaphysite_flavor.9
		miaphysite_flavor.11
		miaphysite_flavor.13
		miaphysite_flavor.15

		conquistador.10
	}
	effect = {
		if = {
			limit = {
				this = location:rome
				religion:catholic = { has_religion_modifier = rome_lost_modifier }
				scope:winner.religion = religion:catholic
			}
			religion:catholic = { remove_religion_modifier = rome_lost_modifier }
		}
		if = {
			limit = {
				this = location:rome
				religion:orthodox = { has_religion_modifier = rome_reclaimed_modifier }
				scope:winner.religion != religion:orthodox
			}
			religion:orthodox = { remove_religion_modifier = rome_reclaimed_modifier }
		}
		if = {
			limit = {
				has_dlc = "d008_fate_of_the_phoenix"
				scope:winner ?= c:BYZ
				root = location:smyrna
			}

			scope:winner = {
				trigger_event_silently = {
					id = fate_of_the_phoenix.2
					days = { 1 90 }
				}
			}
		}
		if = {
			limit = {
				has_dlc = "d008_fate_of_the_phoenix"
				scope:winner ?= c:BYZ
				root = location:iznik
			}

			scope:winner = {
				trigger_event_silently = {
					id = fate_of_the_phoenix.3
					days = { 1 90 }
				}
			}
		}
		if = {
			limit = {
				has_dlc = "d008_fate_of_the_phoenix"
				scope:winner ?= c:BYZ
				root = location:bursa
			}

			scope:winner = {
				trigger_event_silently = {
					id = fate_of_the_phoenix.4
					days = { 1 90 }
				}
			}
		}
		if = {
			limit = {
				scope:winner ?= c:BYZ
				c:BYZ = { has_country_modifier = BYZ_lacking_jewels }
				work_of_art:byzantine_crown_jewels.location ?= root
			}
			work_of_art:byzantine_crown_jewels = {
				save_scope_as = target_woa
			}
			save_scope_as = target
			c:BYZ = {
				trigger_event_non_silently = {
					id = flavor_byz_ven.6
				}
			}
		}
		if = {
			limit = {
				root = location:constantinople
				has_global_variable = hagia_sophia_now_mosque
				scope:winner = { religion.group = religion_group:christian }
			}
			remove_global_variable = hagia_sophia_now_mosque
		}
		if = {
			limit = {
				scope:loser ?= c:PAP
				this = location:rome
				scope:winner.religion = religion:catholic
				scope:winner != c:ITA
			}
			scope:winner = { trigger_event_non_silently = flavor_pap.9002 }
			# Antagonism from all Catholics for seizing the Papal capital, even if Rome is later returned
			religion:catholic = {
				every_country_in_religion = {
					limit = { this != scope:winner }
					add_antagonism = {
						target = scope:winner
						modifier = antagonism_seized_papal_capital
					}
				}
			}
		}
		# Non-Christian takes Rome from the Pope: apply religion-wide penalty to Catholics and fire outrage event
		if = {
			limit = {
				scope:loser ?= c:PAP
				this = location:rome
				NOT = { scope:winner.religion.group = religion_group:christian }
				scope:winner ?= { is_real_country = yes }
			}
			religion:catholic = {
				add_religion_modifier = {
					modifier = rome_lost_modifier
					years = -1
					mode = replace
					desc = as_long_as_location_owner_is_not_catholic_desc
				}
			}
			scope:winner = { trigger_event_non_silently = flavor_pap.9003 }
		}
		if = {
			limit = {
				is_situation_active = situation:fall_of_delhi
				root = situation:fall_of_delhi.var:strongest_claimant_capital
			}
			if = {
				limit = {
					scope:winner = { has_variable = delhi_claimants_variable }
				}
				situation:fall_of_delhi = {
					set_variable = {
						name = strongest_claimant_capital
						value = scope:winner.capital
					}
				}
				set_variable = {
					name = leadership_secured_variable
					value = yes
					years = 1
				}
			}
			else = {
				scope:winner = {
					ordered_known_country = {
						limit = { has_variable = delhi_claimants_variable }
						order_by = {
							value = {
								add = country_total_army_levy_size
								if = {
									limit = { is_subject = yes }
									multiply = 0
								}
								if = {
									limit = { at_war = yes }
									multiply = 0.75
								}
							}
						}
						situation:fall_of_delhi = {
							set_variable = {
								name = strongest_claimant_capital
								value = scope:winner.capital
							}
						}
						set_variable = {
							name = leadership_secured_variable
							value = yes
							years = 1
						}
					}
				}
			}
		}
		if = {
			limit = {
				is_situation_active = situation:rise_of_the_ottomans
				scope:winner ?= { has_reform = government_reform:anatolian_beylik }
				OR = {
					root = location:sivas
					root = location:konya
					root = location:tabriz
					root = location:erzurum
				}
				scope:winner = {
					NOT = { has_estate_privilege = estate_privilege:trunk_road_to_erzurum_privilege }
				}
			}

			scope:winner = { trigger_event_non_silently = rise_of_the_ottomans.218 }
		}
		#Remove Panaqas from foreign locations
		if = {
			limit = {
				has_building = building_type:panaqa_building
				scope:winner = { modifier:has_panaqas = no }
			}
			destroy_building = "building(building_type:panaqa_building|owner)"
		}
		if = {
			limit = {
				has_building = building_type:bey_fortress
				scope:winner = { NOT = { culture ?= { has_culture_group = culture_group:turkic_group } } }
			}
			destroy_building = "building(building_type:bey_fortress|owner)"
		}
		if = {
			limit = {
				is_situation_active = situation:italian_wars
				region = region:italy_region
			}
			if = {
				limit = {
					scope:winner = {
						any_international_organizations_member_of = {
							OR = {
								is_target_in_global_variable_list = {
									name = iw_italian_leagues_list
									target = this
								}
								is_target_in_global_variable_list = {
									name = iw_foreign_leagues_list
									target = this
								}
							}

						}
					}
				}
				every_international_organization_owner = {
					limit = {
						OR = {
							is_target_in_global_variable_list = {
								name = iw_italian_leagues_list
								target = this
							}
							is_target_in_global_variable_list = {
								name = iw_foreign_leagues_list
								target = this
							}
						}
						scope:winner ?= {
							NOT = { is_member_of_international_organization = prev }
						}
					}
					remove_location_from_international_organization = root
				}
				scope:winner ?= {
					random_international_organizations_member_of = {
						limit = {
							OR = {
								is_target_in_global_variable_list = {
									name = iw_italian_leagues_list
									target = this
								}
								is_target_in_global_variable_list = {
									name = iw_foreign_leagues_list
									target = this
								}
							}
						}
						add_location_to_international_organization = root
					}
				}
			}
		}
		if = {
			limit = {
				scope:winner ?= { has_variable = rot_has_selected_core_region }
				root = {
					region = scope:winner.var:rot_has_selected_core_region
					NOT = { integration_level = core }
				}
			}
			root = { change_integration_level = core }
		}
		if = {
			limit = {
				can_fire_situation_event = {
					situation = situation:rise_of_timur
					event = rot_fall_of_delhi
				}
				scope:winner ?= { tag = TIM }
				this = location:delhi
			}
			scope:winner = {
				trigger_event_non_silently = rise_of_timur.11
			}
		}

		if = {
			limit = {
				tag_exists = TUR
				scope:winner ?= { tag = TUR }
				scope:winner = { religion.group = religion_group:muslim }
				this = location:cairo
			}
			scope:winner = {
				trigger_event_non_silently = flavor_tur.204
			}
		}
		if = {
			limit = {
				scope:winner ?= {
					is_human = yes
				}
			}
			scope:winner ?= {
				set_variable = {
					name = unlock_achievement_that_is_mine
					months = 1
				}
			}
		}
		#Pentarchy
		if = {
			limit = {
				has_dlc = "d008_fate_of_the_phoenix"
				root = {
					is_pentarchy_seat = yes
				}
			}
			save_scope_as = target_pentarchy
			scope:winner = {
				if = {
					limit = {
						religion = religion:orthodox
					}
					select_suitable_patriarch = { pentarchy = yes }
					scope:target_patriarch = {
						set_pentarch_variable = { location = scope:target_pentarchy }
					}
					add_pentarchy_modifier = { location = scope:target_pentarchy }
					trigger_event_non_silently = d008_orthodox_events.7
				}
			}
			scope:loser ?= {
				if = {
					limit = { has_pentarchy_modifier = { location = scope:target_pentarchy } }
					if = {
						limit = { has_all_pentarchy_except = { location = scope:target_pentarchy } } #location already has changed hands so it needs to be checked differently
						downgrade_pentarchy_modifier = yes
						set_variable = lost_pentarchy
					}
					remove_pentarchy_modifier = { location = scope:target_pentarchy }
					trigger_event_non_silently = d008_orthodox_events.8
				}
			}
			religion:orthodox = {
				"variable_map(pentarchy|scope:target_pentarchy)" ?= {
					remove_variable = is_pentarch
				}
				remove_from_variable_map = {
					name = pentarchy
					key = scope:target_pentarchy
				}
				if = {
					limit = { exists = scope:target_patriarch }
					add_to_variable_map = {
						name = pentarchy
						key = scope:target_pentarchy
						value = scope:target_patriarch
					}
					scope:target_patriarch = {
						set_variable = {
							name = is_pentarch
							value = scope:target_pentarchy
						}
					}
				}
			}
		}
		if = {
			limit = {
				area = area:morea_area
			}
			if = {
				limit = {
					scope:winner = {
						has_variable = additional_noble_power_for_morea
					}
				}
				add_location_modifier = {
					mode = replace
					modifier = BYZ_morea_nobles
					years = 30
				}
			}
			if = {
				limit = {
					scope:winner = {
						has_variable = BYZ_additional_integration_in_morea
					}
					has_variable = BYZ_unused_integration_bonus
				}
				change_integration_progress = 30
				remove_variable = BYZ_unused_integration_bonus
			}
		}
	}
}

#root = location, scope:old_goods = previous trade goods, scope:new_goods = new trade goods
on_raw_material_changed = {
}

#root = newly formed country
on_new_country_formed = {
	effect = {
		#auto-join anyone who has their capital in the hre
		if = {
			limit = {
				capital = {
					is_owned_by_international_organization = international_organization:hre
				}
				NOT = { is_member_of_international_organization = international_organization:hre }
			}
			international_organization:hre = {
				add_country_to_international_organization = root
			}
		}
		#catholics
		if = {
			limit = {
				religion = religion:catholic
				not = {
					is_member_of_international_organization_of_type = { type = catholic_church }
				}
			}
			international_organization:catholic_church = {
				add_country_to_international_organization = prev
			}
		}

		#shinto
		if = {
			limit = {
				religion = religion:shinto
				not = {
					is_member_of_international_organization_of_type = { type = shinto }
				}
			}
			international_organization:shinto = {
				add_country_to_international_organization = prev
			}
		}
	}
}

#root = released country, scope:overlord = overlord
on_released_country = {
	effect = {
		if = {
			limit = {
				exists = international_organization:hre
				exists = capital
				capital ?= {
					is_owned_by_international_organization = international_organization:hre
				}
				NOT = { is_member_of_international_organization = international_organization:hre }
			}
			international_organization:hre = {
				add_country_to_international_organization_no_update = root
			}
		}
		if = {
			limit = {
				scope:overlord = {
					is_leader_of_international_organization = international_organization:hre
				}
				is_subject = no
			}
			save_scope_as = released_country
			scope:overlord ?= {
				trigger_event_silently = {
					id = hre.901
				}
			}
		}
		if = {
			limit = {
				NOT = {
					is_target_in_global_variable_list = {
						name = eligible_beylik_list
						target = root
					}
				}
				has_reform = government_reform:anatolian_beylik
			}
			add_to_global_variable_list = {
				name = eligible_beylik_list
				target = root
			}
		}
	}
}

#root = new_ruler. target = org. scope:old_ruler = previous leader
on_international_organization_changed_leader = {
	effect = {
		save_scope_as = new_ruler
		#HRE effects:
		if = {
			limit = {
				scope:target = { international_organization_type = international_organization_type:hre }
				game_is_initialized = yes
			}
			# Previous HRE Leader was reelected
			if = {
				limit = {
					exists = scope:old_ruler
					scope:old_ruler = ROOT
					has_ruler = yes
				}
				trigger_event_non_silently = hre.900
			}
			if = {
				limit = {
					OR = {
						imperial_work_of_art_can_be_moved = { work_of_art = work_of_art:imperial_crown_hre country = root international_organization = scope:target }
						imperial_work_of_art_can_be_moved = { work_of_art = work_of_art:imperial_orb_hre country = root international_organization = scope:target }
						imperial_work_of_art_can_be_moved = { work_of_art = work_of_art:saint_stephans_purse country = root international_organization = scope:target }
						imperial_work_of_art_can_be_moved = { work_of_art = work_of_art:coronation_gospel_hre country = root international_organization = scope:target }
					}
				}
				trigger_event_non_silently = hre.800
			}
			# New emperor elected from new country or no previous emperor
			if = {
				limit = {
					OR = {
						NOT = { exists = scope:old_ruler }
						AND = {
							exists = scope:old_ruler
							NOT = { scope:old_ruler = ROOT }
						}
					}
				}
				if = {
					limit = { exists = scope:old_ruler }
					# Update current emperor variable on emperor change
					scope:old_ruler = { remove_variable = hre_current_emperor_flg }
					set_variable = { name = hre_current_emperor_flg value = 1 }
				}
				if = {
					limit = {
						exists = scope:old_ruler
						scope:old_ruler = {
							is_member_of_international_organization = international_organization:ghibellines_io
							NOT = { has_presence_in = region:italy_region }
						}
					}
					international_organization:ghibellines_io = {
						remove_country_from_international_organization = scope:old_ruler
					}
				}
				if = {
					limit = { exists = international_organization:ghibellines_io }
					if = {
						limit = { NOT = { is_member_of_international_organization = international_organization:ghibellines_io } }
						international_organization:ghibellines_io = { add_country_to_international_organization = ROOT }
					}
					trigger_event_silently = guelphs_and_ghibellines.100
				}
			}
			if = {
				limit = {
					exists = scope:old_ruler
					NOT = { scope:old_ruler = root }
					scope:old_ruler = {
						num_subjects > 0
						any_subject = {
							OR = {
								is_subject_type = imperial_free_city
								is_subject_type = direct_imperial_free_city
							}
						}
					}
				}
				scope:old_ruler ?= {
					every_subject = {
						limit = {
							OR = {
								is_subject_type = imperial_free_city
								is_subject_type = direct_imperial_free_city
							}
						}
						overlord = { cancel_subject = prev }
					}
				}
				if = {
					limit = {
						exists = scope:new_ruler
						scope:target = {
							OR = {
								hre_has_free_city_subjects = yes
								hre_has_direct_free_city_subjects = yes
							}
						}
					}
					scope:target = {
						every_international_organization_member = {
							limit = {
								has_special_status_in_international_organization = {
									type = special_status:free_city
									international_organization = scope:target
								}
								NOT = { this = scope:new_ruler }
							}
							if = {
								limit = { scope:target = { hre_has_direct_free_city_subjects = yes } }
								make_subject_of = {
									target = scope:new_ruler
									type = subject_type:direct_imperial_free_city
								}
							}
							else = {
								make_subject_of = {
									target = scope:new_ruler
									type = subject_type:imperial_free_city
								}
							}
						}
					}
				}
			}
			if = {
				limit = {
					OR = {
						scope:target = {
							OR = {
								international_organization_has_policy = policy:expanded_electors_policy
								international_organization_has_policy = policy:elector_council_policy
							}
						}
						modifier:is_excluded_from_electorship = yes
					}
					has_special_status_in_international_organization = {
						type = special_status:elector
						international_organization = international_organization:hre
					}
				}
				scope:target = {
					international_organization_remove_special_status = {
						type = special_status:elector
						country = root
					}
				}
			}
			if = {
				limit = {
					tag = HAB
					is_leader_of_international_organization = international_organization:hre
					international_organization:hre = {
						international_organization_has_law = law:golden_bull
					}
				}
				trigger_event_non_silently = flavor_hab.37
			}
			# Imperial Circles: new Emperor was a circle leader -> relinquish leadership
			if = {
				limit = {
					scope:target = { circles_are_active = yes }
					is_imperial_circle_leader = yes
				}
				trigger_event_non_silently = imperial_circles.80
			}
		}
		#Religious League effects:
		if = {
			limit = {
				scope:target = {
					OR = {
						international_organization_type = international_organization_type:catholic_league
						international_organization_type = international_organization_type:protestant_union
					}
				}
				exists = scope:old_ruler
			}
			scope:old_ruler ?= {
				if = {
					limit = {
						any_casus_belli_target = {
							scope:old_ruler = {
								has_casus_belli_of_type_on = { target = prev type = casus_belli:cb_religious_superiority }
							}
						}
					}
					random_casus_belli_target = {
						limit = {
							scope:old_ruler = {
								has_casus_belli_of_type_on = { target = prev type = casus_belli:cb_religious_superiority }
							}
						}
						save_scope_as = current_religious_enemy_leader
					}
				}
			}
			if = {
				limit = {exists = scope:current_religious_enemy_leader }
				scope:current_religious_enemy_leader = {
					if = {
						limit = { exists = scope:old_ruler }
						remove_casus_belli_mutual_effect = {
							target = scope:old_ruler
							type = casus_belli:cb_religious_superiority
						}
					}
					if = {
						limit = { scope:current_religious_enemy_leader != root }
						add_casus_belli_mutual_effect = {
							target = root
							type = casus_belli:cb_religious_superiority
						}
					}
				}
			}
		}
		#Middle Kingdom effects:
		if = {
			limit = {
				scope:target = { international_organization_type = international_organization_type:middle_kingdom }
				game_is_initialized = yes
				exists = scope:old_ruler
			}
			scope:old_ruler = {
				every_subject = {
					limit = {
						OR = {
							is_subject_type = tributary
							is_subject_type = tusi
						}
						subject_loyalty < MIN_SUBJECT_LOYALTY_FOR_ACTION
					}
					subject_type = {
						save_scope_as = type
					}
					scope:old_ruler = { cancel_subject = prev }
					make_subject_of = {
						target = scope:new_ruler
						type = scope:type
					}
				}
			}
		}
		#Autocephalous patriarchates effects
		if = {
			limit = {
				scope:target = { international_organization_type = international_organization_type:autocephalous_patriarchate }
			}
			scope:target = {
