	effect = {
		if = {
			limit = {
				this = work_of_art:byzantine_crown_jewels
			}
			if = {
				limit = {
					scope:target.owner = {
						OR = {
							has_country_modifier = BYZ_lacking_jewels
							any_country_together_in_war_with = {
								has_country_modifier = BYZ_lacking_jewels
							}
						}
					}
				}
				work_of_art:byzantine_crown_jewels = {
					save_scope_as = target_woa
				}
				scope:location = {
					random_unit_in_location = {
						limit = {
							owner = {
								any_country_together_in_war_with = {
									has_country_modifier = BYZ_lacking_jewels
								}
							}
						}
						save_scope_as = target_army
					}
					random_unit_in_location = {
						limit = {
							owner ?= scope:target.owner
						}
						save_scope_as = target_army
					}
				}
				scope:target.owner = {
					if = {
						limit = {
							has_country_modifier = BYZ_lacking_jewels
						}
						save_scope_as = origin_country
					}
					else = {
						random_country_together_in_war_with = {
							limit = {
								has_country_modifier = BYZ_lacking_jewels
							}
							save_scope_as = origin_country
						}
					}
				}
				if = {
					limit = { # The work of art was brought to Byz
						scope:target.owner = {
							has_country_modifier = BYZ_lacking_jewels
						}
					}
					scope:target.owner = {
						trigger_event_non_silently = {
							id = flavor_byz_ven.6
						}
					}
				}
				else = { # An ally got it - prompt them to have it returned
					scope:target.owner = {
						trigger_event_non_silently = {
							id = flavor_byz_ven.7
						}
					}
				}
			}
			# The work of art is being moved in a diffent country? Notify Byz
			else_if = {
				limit = {
					scope:target.owner = {
						NOT = { has_country_modifier = BYZ_lacking_jewels }
					}
					c:BYZ ?= {
						has_country_modifier = BYZ_lacking_jewels
					}
				}
				save_scope_as = target_woa
				c:BYZ = {
					trigger_event_non_silently = {
						id = flavor_byz_ven.8
					}
				}
			}
		}
	}
}

