#Update the game concepts when you add a new flavor title for the prime minister
add_head_of_cabinet_modifier = {
	add_country_modifier = {
		modifier = $estate$_head_of_cabinet_influence
		days = -1
		mode = add_and_extend
		desc = head_of_cabinet_influence_desc
	}
}

promote_to_head_of_cabinet_effect_base = {
	hidden_effect = {
		every_cabinet_character = {
			limit = {
				has_character_modifier = head_of_the_cabinet_modifier
			}
			remove_head_of_cabinet_effect = yes
		}
		$target$ = {
			add_character_modifier = {
				modifier = head_of_the_cabinet_modifier
				days = -1
				mode = add_and_extend
				recalculate_immediately = yes
			}
		}
	}
	$target$ = {
		promote_to_head_of_cabinet_effect_apply_country_modifier = yes
	}
}

promote_to_head_of_cabinet_effect_apply_country_modifier = {
		if = { 		limit = { has_estate = estate_type:crown_estate }		owner = { add_head_of_cabinet_modifier = { estate = crown_estate } }	}
		else_if = { limit = { has_estate = estate_type:nobles_estate }		owner = { add_head_of_cabinet_modifier = { estate = nobles_estate } }	}
