set_new_ruler_with_union_fratricide = {
	if = {
		limit = { exists = union }
		custom_description = {
			text = set_new_ruler_with_union
			object = $character$
			save_temporary_scope_as = union_country_event_scope
			every_subject = {
				limit = { subject_type = { has_overlords_ruler = yes } }
				set_new_foreign_ruler_no_update = $character$
			}
			union ?= {
				every_international_organization_member = {
					limit = {
						this != scope:union_country_event_scope
						succession_law = heir_selection:fratricide_succesion
					}
					#don't update the unions....yet
					set_new_foreign_ruler_no_update = $character$
					every_subject = {
						limit = { subject_type = { has_overlords_ruler = yes } }
						set_new_foreign_ruler_no_update = $character$
					}
				}
			}
			#now we can update the unions
			set_new_ruler = $character$
			union ?= {
				update_leadership = this
			}
		}
	}
	else = {
		set_new_ruler = $character$
	}
}

set_new_ruler_with_union_if_senior = {
	if = {
		limit = { exists = union }
		save_scope_as = root_country
		if = {
			limit = {
				union ?= {
					country_has_special_status = { type = special_status:senior_partner country = scope:root_country }
				}
			}
			set_new_ruler_with_union = { character = $character$ }
		}
		else = {
			$character$ = { save_scope_as = breakaway_ruler }
			union ?= {
				every_international_organization_member = {
					limit = { this != scope:root_country }
					trigger_event_silently = unionevents.100
				}
			}
			set_new_ruler = $character$
			every_subject = {
				limit = { subject_type = { has_overlords_ruler = yes } }
				set_new_foreign_ruler_no_update = $character$
			}
		}
	}
	else = {
		set_new_ruler = $character$
		every_subject = {
			limit = { subject_type = { has_overlords_ruler = yes } }
			set_new_foreign_ruler_no_update = $character$
		}
	}
}

