move_capital_event_effect = {
	# Only transfer development when the old capital is more developed than the destination
	if = {
		limit = {
			$from$ = { development > $to$.development }
		}

		show_as_tooltip = {
			$to$ = {
				change_development = {
					value = $from$.development
					subtract = $to$.development
					min = 0
					multiply = 0.75
				}
			}
			$from$ = {
				change_development = {
					value = $from$.development
					subtract = $to$.development
					min = 0
					multiply = -0.75
				}
			}
		}

		hidden_effect = {
			set_local_variable = {
				name = difference_between_targets
				value = {
					value = $from$.development
					subtract = $to$.development
					min = 0
					multiply = 0.75
				}
			}

			$to$ = {
				change_development = local_var:difference_between_targets
			}

			$from$ = {
				change_development = {
					value = local_var:difference_between_targets
					multiply = -1
				}
			}
		}
	}

	set_capital = $to$

	$to$ = {
		if = {
			limit = {
				OR = {
					location_rank = location_rank:city
					location_rank = location_rank:megalopolis
				}
			}
			province = {
				every_location_in_province = { change_prosperity = prosperity_mild_bonus }
			}
		}
		else_if = {
			limit = { location_rank = location_rank:town }
			change_location_rank_effect = { location_rank = location_rank:city }
		}
		else = {
			change_location_rank_effect = { location_rank = location_rank:town }
		}
	}

	add_migration = {
		owner = this
		from_location = $from$
		to_location = $to$
		culture = root.culture
		amount = {
			fixed_range = {
				min = {
					value = $from$.population
					divide = 100
				}
				max = {
					value = $from$.population
					multiply = 2
					divide = 100
				}
			}
		}
		months = 6
	}
}

