flavor_byz.28 = { #New Sparta https://en.wikipedia.org/wiki/Constantine_XI_Palaiologos#Despot_of_the_Morea
#Yes, that was a genuine plan for Byzantium
	type = country_event
	title = flavor_byz.28.title
	desc = flavor_byz.28.desc
	outcome = neutral

	fire_only_once = yes

	dynamic_historical_event = {
		tag = BYZ
		from = 1340.1.1
		to = 1453.1.1
		monthly_chance = 1
	}

	trigger = {
		has_or_had_tag = BYZ
		NOT = {
			region:balkan_region = {
				any_ownable_location_in_region = {
					percent > 0.5
					owner = root
				}
			}
		}
		area:morea_area = {
			any_ownable_location_in_area = {
				percent > 0.4
				owner = root
			}
		}
	}

	immediate = {
		ruler_or_regent ?= {
			save_scope_as = target_character
		}
		ordered_owned_location = {
			limit = {
				area = area:morea_area
			}
			order_by = {
				value = population
				multiply = rank_index
				if = {
					limit = { is_coastal = yes }
					multiply = 0.5
				}
				if = {
					limit = { is_border = yes }
					multiply = 5
				}
				multiply = {
					value = 1
					add = modifier:local_defensive
				}
			}
			max = 1
			check_range_bounds = no
			save_scope_as = target_location
		}

		capital = { save_scope_as = target_location2 }
		#event_illustration_estate_background_effect = { background = estate_type:crown_estate }
	}

	option = {
		name = flavor_byz.28.a

		scope:target_location = {
			change_development = development_extreme_bonus
			if = {
				limit = {
					root = { total_building_levels_including_construction:local_governor < modifier:num_local_governors }
					NOT = { has_building = building_type:local_governor }
					OR = { location_rank = location_rank:city  location_rank = location_rank:megalopolis }
				}
				construct_building = {
					building_type = building_type:local_governor
					cost_multiplier = 0.25
					cost_multiplier_reason = "military_cheap_sponsorship"
				}
			}
			construct_building = {
				building_type = building_type:castle
				cost_multiplier = 0.5
				cost_multiplier_reason = "military_cheap_sponsorship"
			}
		}

		change_societal_value = {
			type = offensive_vs_defensive
			value = societal_value_move_to_right
		}

		set_variable = morea_focus_flag
	}

	option = {
		name = flavor_byz.28.b

		change_societal_value = {
			type = offensive_vs_defensive
			value = societal_value_move_to_left
		}
	}
}

