			is_ruler = no
			is_regent = no
			is_heir = no
			has_trait = mamluk
		}
	}

	illustration_tags = {
		10 = interior
		10 = angry
	}

	immediate = {
		ruler_or_regent ?= { save_scope_as = target_character }
		set_variable = {
			name = mamluk_count_var
			value = 1	#Cannot be 0
		}
		if = {
			limit = {
				any_character = {
					count > 4
					is_ruler = no
					is_regent = no
					is_heir = no
					has_trait = mamluk
				}
			}
		}
		every_character = {
			limit = {
				is_ruler = no
				is_regent = no
				is_heir = no
				has_trait = mamluk
			}
			owner = {
				change_variable = {
					name = mamluk_count_var
					add = 1
				}
			}
		}
		if = {
			limit = {
				var:mamluk_count_var > 4
			}
			random_list = {
				1 = {
					change_variable = {
						name = mamluk_count_var
						divide = 3	#We do not want to kill ALL the mamluk characters, only a third
					}
				}
				1 = {
					change_variable = {
						name = mamluk_count_var
						divide = 2	#We do not want to kill ALL the mamluk characters, only half
					}
				}
				1 = { }	#Murder them all!
			}
			while = {
				limit = { var:mamluk_count_var > 0 }
				change_variable = {
					name = mamluk_count_var
					subtract = 1
				}
				random_character = {
					limit = {
						is_ruler = no
						is_regent = no
						is_heir = no
						has_trait = mamluk
					}
					set_variable = potential_mamluk_var
				}
			}
		}
		else = {
			every_character = {
				limit = {
					is_ruler = no
					is_regent = no
					is_heir = no
					has_trait = mamluk
				}
				set_variable = potential_mamluk_var
			}
		}
		set_variable = {
			name = mamluk_purge_side_effect_variable
			value = 0
		}
		every_character = {
			limit = {
				has_variable = potential_mamluk_var
			}
			owner = {
				change_variable = {
					name = mamluk_purge_side_effect_variable
					add = 0.1
				}
			}
		}
		event_illustration_government_estate_effect = yes
	}
	option = {
		name = flavor_mam.18.a

		trigger = {
			manpower_percentage > 0.2
		}

		add_yearly_manpower = {
			value = 1
			add = {
				value = manpower
				divide = 5
			}
			multiply = {
				value = 1
				add = var:mamluk_purge_side_effect_variable
			}
			multiply = -1
		}
		add_army_tradition = {
			value = army_tradition_mild_penalty
			add = {
				value = army_tradition_mild_penalty
				multiply = var:mamluk_purge_side_effect_variable
			}
		}
		every_character = {
			limit = {
				has_variable = potential_mamluk_var
			}
			kill_character = this
		}
	}

	option = {
		name = flavor_mam.18.b

		add_government_power = {
			value = government_power_extreme_penalty
			multiply = {
				value = 1
				add = var:mamluk_purge_side_effect_variable
			}
			multiply = 0.5
		}
		custom_tooltip = mam_backstabs_later_tt
	}

	after = {
		remove_variable = mamluk_purge_side_effect_variable
		remove_variable = mamluk_count_var
		every_character = {
			limit = { has_variable = potential_mamluk_var }
			remove_variable = potential_mamluk_var
			set_variable = rebelling_mamluk_var
		}
	}
}

