	title = flavor_tur.114.title
	desc = flavor_tur.114.desc
	outcome = neutral

	fire_only_once = yes
	dynamic_historical_event = {
		tag = TUR
		from = 1537.1.1
		to = 1637.1.1
		monthly_chance = 10
	}

	historical_info = flavor_tur.114.historical_info

	trigger = {

		has_reform = government_reform:ottoman_imperial_harem

		religion.group = religion_group:muslim

		has_ruler = yes

		ruler ?= { has_dynasty = yes }

		ruler = {
			is_female = no
			exists = mother
			mother = {
				is_alive = yes
				is_ruler = no
				OR = {
					adm >= 60
					dip >= 60
					mil >= 60
				}
			}
		}
	}

	immediate =  {

		root.ruler = { save_scope_as = target_ruler }

		ruler.mother = { save_scope_as = valide_sultan }

		hidden_effect = {
			ruler.mother = {
				add_adm = 5
				add_dip = 10
				add_mil = 5
			}
		}
	}

	option = {
		name = flavor_tur.114.a
		historical_option = yes

		unlock_policy_effect = { type = valide_sultan_court_policy }

		add_policy = policy:valide_sultan_court_policy

		change_societal_value = {
			type = traditionalist_vs_innovative
			value = societal_value_minor_move_to_right
		}

		change_societal_value = {
			type = aristocracy_vs_plutocracy
			value = societal_value_tiny_move_to_left
		}
	}

	option = {
		name = flavor_tur.114.b

		change_societal_value = {
			type = traditionalist_vs_innovative
			value = societal_value_minor_move_to_left
		}
	}
}

flavor_tur.115 = { #The Sultanate of Women
	type = country_event
	title = flavor_tur.115.title
	desc = flavor_tur.115.desc
	outcome = neutral

	fire_only_once = yes
	dynamic_historical_event = {
		tag = TUR
		from = 1537.1.1
		to = 1737.1.1
		monthly_chance = 20
	}

	historical_info = flavor_tur.115.historical_info

	trigger = {

		has_reform = government_reform:ottoman_imperial_harem

		OR = {
			has_policy = valide_sultan_court_policy
			has_policy = harem_policy
		}

		has_ruler = yes
		ruler ?= {
			has_dynasty = yes
			is_female = no
		}

		ruler = {
			dynasty = {
				any_character_in_dynasty = {
					is_female = yes
					is_alive = yes
					is_adult = yes
					owner = root
					count >= 2
				}
			}
		}

		OR = {
			stability < 0
			government_power < 50
			in_civil_war = yes
			has_regent = yes
		}
	}

	immediate =  {

		if = {
			limit = {
				ruler = {
					exists = mother
					mother = {
						is_alive = yes
						owner = root
					}
				}
			}
			ruler.mother = { save_scope_as = harem_power }
		}
		else = {
			ruler = {
				dynasty = {
					ordered_character_in_dynasty = {
						order_by = total_abilities
						limit = {
							owner = root
							is_female = yes
							is_adult = yes
							is_alive = yes
						}
						max = 1
						save_scope_as = harem_power
					}
				}
			}
		}
	}

	option = {
		name = flavor_tur.115.a
		historical_option = yes

		add_country_modifier = { modifier = sultanate_of_women years = 50 mode = add_and_extend }

		if = {
			limit = {
				NOT = {
					has_policy = powerful_harem_policy
				}
			}
			add_policy = policy:powerful_harem_policy
		}

		add_stability = stability_weak_bonus

		change_societal_value = {
			type = traditionalist_vs_innovative
			value = societal_value_minor_move_to_right
		}

		change_societal_value = {
			type = belligerent_vs_conciliatory
			value = societal_value_tiny_move_to_right
		}
	}

	option = {
		name = flavor_tur.115.b

		add_prestige = prestige_weak_bonus

		if = {
			limit = {
				NOT = {
					has_policy = secluded_harem_policy
				}
			}
			add_policy = policy:secluded_harem_policy
		}

		change_societal_value = {
			type = traditionalist_vs_innovative
			value = societal_value_minor_move_to_left
		}
	}
}

scripted_trigger is_slave_origin = {
	OR = {
		religion.group ?= religion_group:christian
		culture ?= culture:circassian_culture
		culture ?= culture:georgian_culture
		culture ?= culture:abkhazian_culture
		NOT = { culture = culture:turkish_culture }
	}
	is_ai = yes
	is_subject = no
	NOR = {
		is_at_war_with = c:TUR
		is_allied_with = { target = c:TUR }
		is_rival_of = c:TUR
		has_opinion = {
			target = ROOT
			modifier = opinion_ottoman_capitulation
		}
	}
}

