# Input: $value$
# Value is mapped to a modifier that is given in THIS.ruler as a character modifier
scripted_effect chi_give_recommendation_modifier_based_on_value = {
	if = {
		limit = {
			$value$ = 1
		}
		ruler = {
			add_character_modifier = {
				mode = add_and_extend
				modifier = chi_recommendation_legalism
				years = -1
			}
		}
	}
	else_if = {
		limit = {
			$value$ = 2
		}
		ruler = {
			add_character_modifier = {
				mode = add_and_extend
				modifier = chi_recommendation_invasions
				years = -1
			}
		}
	}
	else_if = {
		limit = {
			$value$ = 3
		}
		ruler = {
			add_character_modifier = {
				mode = add_and_extend
				modifier = chi_recommendation_traitors
				years = -1
			}
		}
	}
	else_if = {
		limit = {
			$value$ = 4
		}
		ruler = {
			add_character_modifier = {
				mode = add_and_extend
				modifier = chi_recommendation_public_works
				years = -1
			}
		}
	}
	else_if = {
		limit = {
			$value$ = 5
		}
		ruler = {
			add_character_modifier = {
				mode = add_and_extend
				modifier = chi_recommendation_legislation
				years = -1
			}
		}
	}
}

