			limit = {
				OR = {
					NOT = { exists = scope:target_character }
					scope:target_character = { is_alive = no }
				}
			}
			horde_assign_pretender_leader_character = yes
			var:pretender_rebel_character ?= { save_scope_as = target_character }
		}
