			limit = {
				in_civil_war = yes
				civil_war_opponent = {
					has_ruler = yes
					ruler ?= scope:target_character
				}
			}
			scope:target_character = { move_country = scope:target_country }
			civil_war_opponent = {
				scope:target_country = { annex_country = { country = prev } }
			}
		}
		set_new_ruler = scope:target_character
		scope:target_character = {
