sinicization_disaster.100 = {
	type = country_event
	category = disaster_event
	title = sinicization_disaster.100.title
	desc = {
		first_valid = {
			triggered_desc = {
				desc = sinicization_disaster.100.desc.a	#China Influence Wins
				trigger = {
					var:china_side >= 30
				}
			}
			triggered_desc = {
				desc = sinicization_disaster.100.desc.b	#Sovereign Influence Wins
				trigger = {
					var:sovereign_side >= 30
				}
			}
			triggered_desc = {
				desc = sinicization_disaster.100.desc.c	#We outgrew China
				trigger = {
					OR = {
						country_economical_base > {
							value = c:CHI.country_economical_base
							multiply = 0.75
						}
						societal_value:sinicized_vs_unsinicized > 0
						NOT = { country_exists = c:CHI }
					}
				}
			}
			triggered_desc = {
				desc = sinicization_disaster.100.desc.d	#We are a subject of China
				trigger = {
					is_subject_or_below_of = c:CHI
				}
			}
			triggered_desc = {
				desc = sinicization_disaster.100.desc.e	#Fallback
				trigger = {
					always = yes
				}
			}
		}
	}
	outcome = neutral

	image = "gfx/interface/illustrations/disaster/sinicization_disaster.dds"

	major = yes
	major_trigger = {
		OR = {
			this = c:CHI
			AND = {
				exists = scope:shafted_overlord
				this = scope:shafted_overlord
			}
		}
	}

	immediate = {
		save_scope_as = target_sinicized_country
		chi_scopes = yes

		if = {
			limit = {
				is_subject = yes
				NOT = { is_subject_or_below_of = c:CHI }
			}
			overlord = { save_scope_as = shafted_overlord }
		}
	}

	option = {
		name = sinicization_disaster.100.a

		trigger = { var:china_side >= 30 }

		if = {
			limit = { exists = scope:shafted_overlord }
			scope:shafted_overlord = { cancel_subject = root }
		}

		make_subject_of = {
			target = c:CHI
			type = subject_type:tributary
		}
	}

	option = {
		name = sinicization_disaster.100.b

		trigger = { var:china_side >= 30 }

		c:CHI = {
			add_casus_belli =  {
				target = root
				type = casus_belli:cb_subject_broke_free
			}

			hidden_effect = {
				if = {
					limit = { is_ai = yes }
					random_list = {
						1 = {
							if = {
								limit = {
									can_declare_legal_war_on = { target = root }
								}
								declare_war_with_cb = {
									target = root
									type = casus_belli:cb_subject_broke_free
								}
							}
						}
						1 = { }
					}
				}
			}
		}
	}

	option = {
		name = sinicization_disaster.100.c

		trigger = {
			OR = {
				country_economical_base > {
					value = c:CHI.country_economical_base
					multiply = 0.75
				}
				societal_value:sinicized_vs_unsinicized > 0
				NOT = { country_exists = c:CHI }
			}
		}

		add_country_modifier = {
			modifier = victory_over_china
			years = modifier_duration_years_long
			mode = replace
