turmoil_in_brandenburg.1303  = {
	type = country_event
	category = disaster_event
	title = turmoil_in_brandenburg.1303.title
	desc = turmoil_in_brandenburg.1303.desc
	outcome = neutral
	image = "gfx/interface/illustrations/disaster/turmoil_in_brandenburg.dds"
	fire_only_once = yes
	dynamic_historical_event = {
		tag = BRA
		tag = PRU
		from = 1372.1.1
		to = 1821.1.1 #Robber baron issue must be able to be resolved
		monthly_chance = 20
	}


	trigger = {
		has_variable = PRU_robber_barons_active
		OR = {
			any_province = {
				percent >= 0.75
				NOT = { has_province_modifier = PRU_robber_barons }
				has_variable = pru_has_had_robber_barons
			}
			AND = {
				NOT = {
					has_variable = robber_barons_issues_are_ignored
					has_variable = robber_barons_issues_are_dealt_with
				}
			}
		}
