latinization_vs_hellenization.28 = {	#Nobles Resist Current Trend
	type = country_event
	title = latinization_vs_hellenization.28.title
	desc = latinization_vs_hellenization.28.desc
	outcome = neutral
	trigger = {
		has_dlc = "d008_fate_of_the_phoenix"
		has_societal_value = societal_value_type:latinization_vs_hellenization
		country_has_estate = estate_type:nobles_estate

		OR = {
			modifier:monthly_towards_latinization > modifier:monthly_towards_hellenization
			modifier:monthly_towards_hellenization > modifier:monthly_towards_latinization
		}
	}

	illustration_tags = {
		10 = angry
		10 = interior
	}

	immediate = {
		event_illustration_estate_effect = { foreground = estate_type:nobles_estate background = estate_type:nobles_estate }

		#Mark which way the current "wind" blows
		if = {
			limit = {
				modifier:monthly_towards_latinization > modifier:monthly_towards_hellenization
			}
			set_variable = LvH_event_28_latin_trend_variable
		}
		else_if = {
			limit = {
				modifier:monthly_towards_hellenization > modifier:monthly_towards_latinization
			}
			set_variable = LvH_event_28_greek_trend_variable
		}
	}

	option = {	#Concede to their demands
		name = latinization_vs_hellenization.28.a

		add_estate_satisfaction = {
			type = estate_type:nobles_estate
			value = estate_satisfaction_mild_bonus
		}

		#Nobles pull against the prevailing current, trying to "steady the realm"
		if = {
			limit = { has_variable = LvH_event_28_latin_trend_variable }
			#Current drift favours Latinization → nobles lean Hellenic
			change_societal_value = {
				type = latinization_vs_hellenization
				value = societal_value_minor_move_to_right
			}
		}
		else_if = {
			limit = { has_variable = LvH_event_28_greek_trend_variable }
			#Current drift favours Hellenization → nobles lean Latin
			change_societal_value = {
				type = latinization_vs_hellenization
				value = societal_value_minor_move_to_left
			}
		}
	}

	option = {	#We will not change course
		name = latinization_vs_hellenization.28.b

		add_estate_satisfaction = {
			type = estate_type:nobles_estate
			value = estate_satisfaction_mild_penalty
		}

		#Ignoring them lets the current trend deepen
		if = {
			limit = { has_variable = LvH_event_28_latin_trend_variable }
			#Reinforce Latin drift
			change_societal_value = {
				type = latinization_vs_hellenization
				value = societal_value_tiny_move_to_left
			}
		}
		else_if = {
			limit = { has_variable = LvH_event_28_greek_trend_variable }
			#Reinforce Greek drift
			change_societal_value = {
				type = latinization_vs_hellenization
				value = societal_value_tiny_move_to_right
			}
		}
	}

	after = {
		hidden_effect = {
			remove_variable = LvH_event_28_latin_trend_variable
			remove_variable = LvH_event_28_greek_trend_variable
		}
	}
}


