scripted_effect setup_chinese_culture_scope = {	#Grabs the culture of the Middle Kingdom Leader if that exists
	if = {
		limit = {
			is_member_of_international_organization = international_organization:middle_kingdom
			NOT = { is_leader_of_international_organization = international_organization:middle_kingdom }
			international_organization:middle_kingdom = {
				international_organization_has_leader = yes
				leader_country.culture = {
					has_culture_group = culture_group:chinese_group
				}
			}
		}
		international_organization:middle_kingdom.leader_country = {
			culture = { save_scope_as = target_culture }
		}
	}
	else = {
		culture_group:chinese_group = {
			random_culture_in_culture_group = {
				limit = {
					ROOT = {
						culture_percentage_in_country = {
							culture = prev
							value > 0
						}
					}
				}
				save_scope_as = target_culture
			}
		}
	}
}

