societal_values.2318 = {	#Chinese Merchants settle <place>
	type = country_event
	title = societal_values.2318.title
	desc = societal_values.2318.desc
	outcome = neutral

	illustration_tags = {
		10 = regular
		10 = interior
	}

	trigger = {
		num_of_non_rural > 0
		has_societal_value = societal_value_type:sinicized_vs_unsinicized
		societal_value:sinicized_vs_unsinicized < -50
		is_member_of_international_organization = international_organization:middle_kingdom
		NOT = { is_leader_of_international_organization = international_organization:middle_kingdom }
		any_market_with_merchants = { has_merchant = international_organization:middle_kingdom.leader_country }
		is_neighbor_of = international_organization:middle_kingdom.leader_country
		any_owned_non_rural_location = {
			market = { has_merchant = international_organization:middle_kingdom.leader_country }
		}
	}

	immediate = {
        event_illustration_estate_effect = { foreground = estate_type:nobles_estate background = estate_type:nobles_estate }
		international_organization:middle_kingdom.leader_country = { save_scope_as = target_country }
		ordered_owned_non_rural_location = {
			limit = {
				market = { has_merchant = scope:target_country }
			}
			order_by = {
				value = location_population_percentage
				multiply = -1
				if = {	#More likely to choose locations whose market has merchants from scope:target_country!
					limit = {
						market = { has_merchant = scope:target_country }
					}
					divide = 0.5
				}
			}
			max = 8
			check_range_bounds = no
			add_to_list = 2318_destination_list
			#Above we take a location and not a province definition. This is because the central chosen location
			#is needed to calculate the distance between itself and the location origin of the migrants in scope:target_country
		}
		random_in_list = {
			list = 2318_destination_list
			save_scope_as = target_location_destination
			province_definition = { save_scope_as = target_province_definition_destination }
			#Here, to help ourselves, we save the province definition of the selected location as a scope

			province = { save_scope_as = target_province_origin }
		}
		scope:target_country = {
			ordered_owned_non_rural_location = {
				order_by = {
					value = "distance_to_squared(scope:target_location_destination)"
					multiply = -1
					if = {	#More likely to choose locations whose market has merchants from ROOT/us
						limit = {
							market = { has_merchant = ROOT }
						}
						divide = 0.5
					}
				}
				max = 8
				check_range_bounds = no
				province_definition = {
					add_to_list = 2318_origin_list
				}
			}
		}
		random_in_list = {
			list = 2318_origin_list
			save_scope_as = target_province_definition_origin
		}
	}

	option = {	#An influx of Merchants is a good thing, right?
		name = societal_values.2318.a

		add_migration = {
			owner = scope:target_country
			from = scope:target_province_definition_origin
			to = scope:target_province_definition_destination
			type = pop_type:burghers
			amount = {
				value = {
					add = scope:target_province_origin.population
					multiply = {0.001 0.002 }
				}
			}
			months = 6
		}

		change_societal_value = {
			type = sinicized_vs_unsinicized
			value = societal_value_minor_move_to_left
		}
	}
}


