	set_variable = rtr_release_tag_CTW
	set_variable = rtr_release_tag_CGU
	set_variable = rtr_release_tag_CNP
	set_variable = rtr_release_tag_CDN
	set_variable = rtr_release_tag_CSI
	set_variable = rtr_release_tag_CKO
