				value = war_exhaustion
				multiply = 5
			}
		}
	}
	option = {
		name = red_turban_rebellions.1001.b
		hidden_effect = {
			scope:root_country = {
				every_current_war = {
					limit = {
						is_on_same_side = {
							country = scope:root_country
							target = scope:target_country
						}
					}
					save_scope_as = target_war
					if = {
						limit = {
							attacker_leader != scope:root_country
							defender_leader != scope:root_country
						}
						scope:root_country = {
							leave_war = {
								war = scope:target_war
								actor = this
							}
						}
					}
					else = {
						scope:target_country = {
							leave_war = {
								war = scope:target_war
								actor = scope:target_country
							}
						}
					}
				}
			}
		}
		scope:root_country = {
			if = {
				limit = {
					can_declare_legal_war_on = { target = scope:target_country }
				}
				declare_war_with_cb = {
					target = scope:target_country
